mapper.insert:

    SELECT
        'SECT'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(SECT_NO), LENGTH('SECT' ) + 1)), 0) + 1, 6, '0')
    FROM PRJ_SECTION

INSERT INTO PRJ_SECTION (
	SECT_NO
	, PRJ_NO
	, USER_ID
	, SECT_NAME
	, SECT_ORDER
) VALUES (
	#{sectNo}
	, #{prjNo}
	, #{userId}
	, #{sectName}
	, #{sectOrder}
)

mapper.update:
UPDATE PRJ_SECTION
SET 
	PRJ_NO = #{prjNo}
	, USER_ID = #{userId}
	, SECT_NAME = #{sectName}
	, SECT_ORDER = #{sectOrder}
	, DELETE_DATE = #{deleteDate}
	, DEL_USER_ID = #{delUserId}
WHERE SECT_NO = #{sectNo}
